using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Greets a user by name.")]
    public static string Greet(
        [Description("The name of the person to greet")] string name) =>
        $"Hello, {name}! Welcome to the HTTP MCP Server.";

    [McpServerTool, Description("Adds two numbers together and returns the result.")]
    public static double Add(
        [Description("First number")] double a,
        [Description("Second number")] double b) =>
        a + b;
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ServerResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns current application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(new
        {
            version = "1.0.0",
            environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            features = new { darkMode = true, notifications = true },
            maxConnections = 100
        }, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(
        UriTemplate = "info://server",
        Name = "Server Info",
        MimeType = "application/json"),
     Description("Returns server runtime information.")]
    public static string GetServerInfo() =>
        JsonSerializer.Serialize(new
        {
            machineName = Environment.MachineName,
            osVersion = Environment.OSVersion.ToString(),
            dotnetVersion = Environment.Version.ToString(),
            timestamp = DateTime.UtcNow
        }, new JsonSerializerOptions { WriteIndented = true });
}

